// Normalize raw portal payload (Zillow, Realtor.com, or brokerage site) into canonical schema.
const body = $input.first().json.body || $input.first().json;
const headers = $input.first().json.headers || {};

function detectSource(payload, headers) {
  if (payload.leadSource && String(payload.leadSource).toLowerCase().includes('zillow')) return 'zillow';
  if (payload.source_name && String(payload.source_name).toLowerCase().includes('realtor')) return 'realtor_com';
  if (payload.formId || payload.website_form) return 'brokerage_site';
  const path = (headers['x-source-path'] || '').toLowerCase();
  if (path.includes('zillow')) return 'zillow';
  if (path.includes('realtor')) return 'realtor_com';
  return 'brokerage_site';
}

function toE164(rawPhone) {
  if (!rawPhone) return null;
  const digits = String(rawPhone).replace(/\D/g, '');
  if (digits.length === 10) return `+1${digits}`;
  if (digits.length === 11 && digits.startsWith('1')) return `+${digits}`;
  return null;
}

function normalizeEmail(rawEmail) {
  if (!rawEmail) return null;
  return String(rawEmail).trim().toLowerCase();
}

function priceBand(price) {
  if (price === null || price === undefined || Number.isNaN(price)) return 'unknown';
  if (price < 300000) return 'under_300k';
  if (price < 500000) return '300k-500k';
  if (price < 750000) return '500k-750k';
  return '750k-plus';
}

function parsePrice(raw) {
  if (raw === null || raw === undefined) return null;
  const cleaned = String(raw).replace(/[^0-9.]/g, '');
  if (!cleaned) return null;
  const value = parseInt(cleaned, 10);
  return Number.isNaN(value) ? null : value;
}

const source = detectSource(body, headers);

let firstName = null, lastName = null, email = null, phone = null;
let propertyAddress = null, listingRef = null, listPrice = null, inquiryNote = null, capturedAt = null;

if (source === 'zillow') {
  const person = body.person || {};
  firstName = person.firstName || null;
  lastName = person.lastName || null;
  email = normalizeEmail(person.emailAddress);
  phone = toE164(person.phoneNumber);
  propertyAddress = body.propertyAddress || null;
  listingRef = body.listingId || null;
  listPrice = parsePrice(body.listPrice);
  inquiryNote = body.message || null;
  capturedAt = body.createdAt || null;
} else if (source === 'realtor_com') {
  const contact = body.contact || {};
  const listing = body.listing || {};
  const fullName = contact.full_name || '';
  const parts = fullName.trim().split(/\s+/);
  firstName = parts[0] || null;
  lastName = parts.slice(1).join(' ') || null;
  email = normalizeEmail(contact.email);
  phone = toE164(contact.phone);
  propertyAddress = [listing.address_line1, listing.address_line2].filter(Boolean).join(', ') || null;
  listingRef = listing.mls_id || null;
  listPrice = parsePrice(listing.price);
  inquiryNote = body.comments || null;
  capturedAt = body.submitted_at || null;
} else {
  // brokerage_site fallback shape
  firstName = body.firstName || body.first_name || null;
  lastName = body.lastName || body.last_name || null;
  email = normalizeEmail(body.email);
  phone = toE164(body.phone);
  propertyAddress = body.propertyAddress || body.address || null;
  listingRef = body.listingRef || body.listing_id || null;
  listPrice = parsePrice(body.listPrice || body.price);
  inquiryNote = body.message || body.comments || null;
  capturedAt = body.createdAt || body.submitted_at || null;
}

let timestampInferred = false;
if (!capturedAt || Number.isNaN(Date.parse(capturedAt))) {
  capturedAt = new Date().toISOString();
  timestampInferred = true;
}

// Form completeness: share of optional fields populated (address, listingRef, price, note)
const optionalFields = [propertyAddress, listingRef, listPrice, inquiryNote];
const formCompleteness = optionalFields.filter((f) => f !== null && f !== undefined && f !== '').length / optionalFields.length;

const emailInvalid = email ? !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) : false;
const phoneInvalid = phone === null && Boolean(
  (source === 'zillow' && body.person && body.person.phoneNumber) ||
  (source === 'realtor_com' && body.contact && body.contact.phone) ||
  (source === 'brokerage_site' && body.phone)
);

const hasIdentifier = Boolean((email && !emailInvalid) || (phone && !phoneInvalid));

return [{
  json: {
    leadId: null,
    source,
    sourceLeadType: body.inquiryType || body.lead_type || 'buyer_inquiry',
    firstName,
    lastName,
    email,
    phone,
    propertyAddress,
    listingRef,
    listPrice,
    priceBand: priceBand(listPrice),
    inquiryNote,
    capturedAt,
    timestampInferred,
    formCompleteness,
    emailInvalid,
    phoneInvalid,
    hasIdentifier,
    dedupeKeyEmail: email,
    dedupeKeyPhone: phone ? phone.replace(/\D/g, '') : null
  }
}];

