// Compute 0-100 lead score from source weight, price band, and form completeness.
const SOURCE_WEIGHTS = { zillow: 30, realtor_com: 25, brokerage_site: 20 };
const PRICE_BAND_WEIGHTS = { under_300k: 10, '300k-500k': 15, '500k-750k': 20, '750k-plus': 25 };

const item = $input.first().json;

let sourceScore, priceScore, completenessScore, score, tier;
try {
  sourceScore = SOURCE_WEIGHTS[item.source] ?? 15;
  priceScore = PRICE_BAND_WEIGHTS[item.priceBand] ?? 10;
  completenessScore = Math.round((item.formCompleteness ?? 0) * 25);
  score = Math.min(100, sourceScore + priceScore + completenessScore);
} catch (err) {
  // Fail-safe: scoring errors never block enrollment (Section 14/21 of SOP).
  score = 40;
}

if (score >= 70) tier = 'fast_track';
else if (score >= 40) tier = 'standard';
else tier = 'long_cycle';

// Unknown source enum never fast-tracks, per data validation rule.
if (!['zillow', 'realtor_com', 'brokerage_site'].includes(item.source) && tier === 'fast_track') {
  tier = 'standard';
}

return [{
  json: {
    ...item,
    score,
    tier
  }
}];

